/// Convert a number, possibly with a fractional part, from base src_base
/// to base dst_base.
/// value is an optional leading '-', then 1 to 10 digits, then optionally a
/// '.' followed by 1 to 10 digits (so "1." and ".5" are not accepted).
/// Digits are 0-9 then the letters a-z for 10 to 35, in either case, and
/// every digit must be below src_base. Leading zeros are allowed.
/// The result is the exact value of value truncated toward zero to at most
/// frac_digits digits after the point, written in base dst_base with digits
/// 0-9 then lowercase a-z: the integer part with no leading zeros ("0" when
/// it is zero), then a '.' and the fractional digits with trailing zeros
/// removed (no '.' at all when no fractional digit remains), and a '-'
/// prefix only when the written result is not zero (never "-0").
/// Return the string "invalid" if src_base or dst_base is outside 2..36,
/// if frac_digits is negative, or if value is not of the form above.
/// >>> convert_base("0.1", 10, 2, 8)
/// String::from("0.00011001")
/// >>> convert_base("-ff.8", 16, 10, 3)
/// String::from("-255.5")
fn convert_base(value: &str, src_base: i64, dst_base: i64, frac_digits: i64) -> String {
    let invalid = String::from("invalid");
    if !(2..=36).contains(&src_base) || !(2..=36).contains(&dst_base) || frac_digits < 0 {
        return invalid;
    }
    let (neg, body) = match value.strip_prefix('-') {
        Some(b) => (true, b),
        None => (false, value),
    };
    let (whole, frac) = match body.split_once('.') {
        Some((w, f)) => (w, Some(f)),
        None => (body, None),
    };
    let w = match parse(whole, src_base) {
        Some(n) => n,
        None => return invalid,
    };
    let (mut f, den) = match frac {
        None => (0, 1),
        Some(fs) => match parse(fs, src_base) {
            Some(n) => (n, src_base.pow(fs.len() as u32)),
            None => return invalid,
        },
    };
    let digit = |d: i64| char::from_digit(d as u32, 36).unwrap();
    let mut int_digits = Vec::new();
    let mut n = w;
    while n > 0 {
        int_digits.push(digit(n % dst_base));
        n /= dst_base;
    }
    let mut out: String = int_digits.iter().rev().collect();
    if out.is_empty() {
        out.push('0');
    }
    let mut fd = String::new();
    while f > 0 && (fd.len() as i64) < frac_digits {
        f *= dst_base;
        fd.push(digit(f / den));
        f %= den;
    }
    let fd = fd.trim_end_matches('0');
    if !fd.is_empty() {
        out.push('.');
        out.push_str(fd);
    }
    if neg && out != "0" {
        out.insert(0, '-');
    }
    out
}

fn parse(s: &str, base: i64) -> Option<i64> {
    if s.is_empty() || s.len() > 10 {
        return None;
    }
    let mut n: i64 = 0;
    for c in s.chars() {
        let d = c.to_digit(36)? as i64;
        if d >= base {
            return None;
        }
        n = n * base + d;
    }
    Some(n)
}
